def longest_common_subsequence(string1, string2):
    m = len(string1)
    n = len(string2)

    # Create a table to store the lengths of common subsequence
    pd = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the table using dynamic programming
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if string1[i-1] == string2[j-1]:
                pd[i][j] = pd[i-1][j-1] + 1
            else:
                pd[i][j] = max(pd[i-1][j], pd[i][j-1])

    # backtrack to find the actual subsequence
    longest_subsequence = ""
    i, j = m, n
    while i > 0 and j > 0:
        if string1[i-1] == string2[j-1]:
            longest_subsequence = string1[i-1] + longest_subsequence
            i -= 1
            j -= 1
        elif pd[i-1][j] > pd[i][j-1]:
            i -= 1
        else:
            j -= 1

    return longest_subsequence

